-- private.lock_doors()
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION private.lock_doors()
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare f record; t record; was text;
begin
  was := coalesce(nullif(current_setting('lock_timeout', true), ''), '0');
  perform set_config('lock_timeout', '4s', true);
  perform private.pace_doors();
  perform private.once_doors();
  perform private.guard_doors();

  for f in
    select p.oid::regprocedure as sig, p.proname
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
  loop
    -- Functions are locked on their own row rather than on a table, and
    -- nothing reading the island takes a conflicting lock on one, so these
    -- have never been part of the race and are left as they were.
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    if f.proname like 'rpc\_%' then
      execute format('grant execute on function %s to authenticated', f.sig);
    end if;
    if f.proname = 'rpc_name_free' then
      execute format('grant execute on function %s to anon', f.sig);
    end if;
  end loop;

  -- The rulebook: readable by everyone, writable by nobody.
  for t in
    select c.oid, c.relname, c.relrowsecurity from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public' and c.relkind = 'r' and c.relname <> 'world'  -- an island's own row: `world_read`
      and not exists (
        select 1 from pg_attribute a
        where a.attrelid = c.oid and a.attname in ('world_id', 'uid')
          and a.attnum > 0 and not a.attisdropped)
  loop
    if not t.relrowsecurity then
      perform private.shut(format('alter table public.%I enable row level security', t.relname));
    end if;
    /*
     * The read policy, and only when what is there is not already exactly it:
     * the right name, on select, open to those two roles and to nobody else,
     * with `true` for its terms. Anything else — a policy somebody narrowed,
     * widened, or pointed at another command — is dropped and written again.
     */
    if not exists (
      select 1 from pg_policy p
      where p.polrelid = t.oid and p.polname = t.relname || '_read'
        and p.polcmd = 'r' and p.polpermissive
        and pg_get_expr(p.polqual, p.polrelid) = 'true'
        and (select coalesce(array_agg(r.rolname::text order by r.rolname), '{}')
               from pg_roles r where r.oid = any(p.polroles)) = array['anon', 'authenticated']
    ) then
      perform private.shut(format('drop policy if exists %I on public.%I', t.relname || '_read', t.relname));
      perform private.shut(format('create policy %I on public.%I for select to anon, authenticated using (true)',
        t.relname || '_read', t.relname));
    end if;
    if not (has_table_privilege('anon', t.oid, 'select')
            and has_table_privilege('authenticated', t.oid, 'select')) then
      perform private.shut(format('grant select on public.%I to anon, authenticated', t.relname));
    end if;
    if exists (
      select 1 from unnest(array['anon', 'authenticated']) as role,
                    unnest(array['insert', 'update', 'delete', 'truncate']) as priv
      where has_table_privilege(role, t.oid, priv)
    ) then
      perform private.shut(format('revoke insert, update, delete, truncate on public.%I from anon, authenticated', t.relname));
    end if;
  end loop;


  -- Every table and view in public, the rulebook or not: row security on, and
  -- nothing for a browser's roles but SELECT, column grants included.
  for t in
    select c.oid, c.relname, c.relkind, c.relrowsecurity,
           (select string_agg(distinct a.privilege_type, ', ')
              from (select x.privilege_type, x.grantee from aclexplode(c.relacl) x
                    union all
                    select y.privilege_type, y.grantee
                      from pg_attribute att, aclexplode(att.attacl) y
                     where att.attrelid = c.oid and att.attnum > 0 and att.attacl is not null) a
             where a.privilege_type <> 'SELECT'
               and a.grantee in (0, 'anon'::regrole::oid, 'authenticated'::regrole::oid)) as extra
    from pg_class c join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public' and c.relkind in ('r', 'p', 'v', 'm', 'f')
  loop
    if t.relkind in ('r', 'p') and not t.relrowsecurity then
      perform private.shut(format('alter table public.%I enable row level security', t.relname));
    end if;
    if t.extra is not null then
      perform private.shut(format('revoke %s on public.%I from public, anon, authenticated', t.extra, t.relname));
    end if;
  end loop;

  -- Every sequence in public: nothing for anon, authenticated or PUBLIC. The doors run as their owner.
  for t in
    select c.relname from pg_class c
    where c.relnamespace = 'public'::regnamespace and c.relkind = 'S'
      and exists (select 1 from aclexplode(c.relacl) a
                  where a.grantee in (0, 'anon'::regrole::oid, 'authenticated'::regrole::oid))
  loop
    perform private.shut(format('revoke all on sequence public.%I from public, anon, authenticated', t.relname));
  end loop;
  -- anon reads the rulebook and nothing with an island or a body on it.
  for t in
    select c.relname from pg_class c
    where c.relnamespace = 'public'::regnamespace and c.relkind in ('r', 'p', 'v', 'm', 'f')
      and (c.relname = 'world' or exists (
        select 1 from pg_attribute a
        where a.attrelid = c.oid and a.attname in ('world_id', 'uid') and a.attnum > 0 and not a.attisdropped))
      and exists (select 1 from aclexplode(c.relacl) a
                  where a.grantee in (0, 'anon'::regrole::oid) and a.privilege_type = 'SELECT')
  loop
    perform private.shut(format('revoke select on public.%I from public, anon', t.relname));
  end loop;
  -- Nothing in private is executable by anon or PUBLIC; authenticated only what was granted by name.
  for f in
    select p.oid::regprocedure as sig, p.proname from pg_proc p
    where p.pronamespace = 'private'::regnamespace
      and exists (select 1 from aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
                  where a.privilege_type = 'EXECUTE' and a.grantee in (0, 'anon'::regrole::oid))
  loop
    execute format('revoke execute on function %s from public, anon', f.sig);
  end loop;

  -- `item`: authenticated reads every column but where the thing came from (`origin`, `origin_fn`,
  -- `origin_uid`), which are the watch's and the keepers'.
  if exists (select 1 from pg_class c, aclexplode(c.relacl) a
              where c.oid = 'public.item'::regclass and a.privilege_type = 'SELECT'
                and a.grantee in (0, 'anon'::regrole::oid, 'authenticated'::regrole::oid)) then
    perform private.shut('revoke select on public.item from public, anon, authenticated');
  end if;
  perform private.shut(format('grant select (%s) on public.item to authenticated', s.cols))
    from (select string_agg(quote_ident(a.attname), ', ' order by a.attnum) as cols from pg_attribute a
           where a.attrelid = 'public.item'::regclass and a.attnum > 0 and not a.attisdropped
             and a.attname not in ('origin', 'origin_fn', 'origin_uid')
             and not has_column_privilege('authenticated', a.attrelid, a.attnum, 'select')) s
   where s.cols is not null;
  if exists (select 1 from pg_attribute a, aclexplode(a.attacl) x
              where a.attrelid = 'public.item'::regclass and a.attname in ('origin', 'origin_fn', 'origin_uid')
                and x.privilege_type = 'SELECT'
                and x.grantee in (0, 'anon'::regrole::oid, 'authenticated'::regrole::oid)) then
    perform private.shut('revoke select (origin, origin_fn, origin_uid) on public.item from public, anon, authenticated');
  end if;

  perform set_config('lock_timeout', was, true);
end $function$
